#!/usr/bin/env bash
# Doc dev à jour, 1/2 — extraits réalignés et groupes système.
# - « Le compte et le profil » : parcours guidés de la création d'un compte et de l'action du profil réalignés
#   (statut, majorité, cours ; date de naissance du mineur demandée à son parent) ;
# - « Le modèle exécutable », « Valider l'entrée » : extraits corrigés ;
# - « Les groupes » : section « Les groupes système : Instructeurs et Bureau » ;
# - commentaires de code périmés corrigés. Pas de migration.
# Prérequis : apply-date-naissance-3-tests-doc.sh.
# Usage (racine du repo) : bash apply-doc-a-jour-1.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null | grep -qF "Les groupes système : Instructeurs et Bureau"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Date de naissance demandée au parent" "e2e/date-de-naissance-parent.spec.ts" 2>/dev/null || { echo "lancez d'abord apply-date-naissance-3-tests-doc.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/api/valider-l-entree.mdx" "apps/web/content/docs/dev/donnees/le-modele-executable.mdx" "apps/web/content/docs/dev/membres/les-groupes.mdx" "apps/web/content/docs/dev/membres/profil-et-premiere-connexion.mdx" "apps/web/src/features/admin/users/forms/update-me/updateMeForm.action.ts" "apps/web/src/features/docs/entities/procedureMap.generated.json" "packages/backend/src/modules/users/router.ts")
CREATED=()
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "Les groupes système : Instructeurs et Bureau" "apps/web/content/docs/dev/membres/les-groupes.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR


python3 - <<'PY'
import base64
spec_skip_done = False
def sub(path, old, new):
    old, new = base64.b64decode(old).decode(), base64.b64decode(new).decode()
    s = open(path, encoding="utf-8").read()
    if s.count(old) == 0 and s.count(new) == 1 and spec_skip_done: return  # déjà fait par un script précédent
    assert s.count(old) == 1, (path, old[:80], s.count(old))
    open(path, "w", encoding="utf-8").write(s.replace(old, new))
